def key_value_store_operations(operations):
    store = defaultdict(None)
    results = []
    for operation in operations:
        if operation[0] == 'set':
            store[operation[1]] = operation[2]
        elif operation[0] == 'get':
            results.append(store.get(operation[1], None))
        elif operation[0] == 'delete':
            if operation[1] in store:
                del store[operation[1]]
