def extract_json_value(html_content, key):
    # Find the script tag with type 'application/ld+json'
    script_tag = re.search(r'<script type="application/ld\+json">(.*?)</script>', html_content, re.DOTALL)
    if not script_tag:
        return None

    # Extract the JSON content from the script tag and parse it
    json_content = script_tag.group(1)
    try:
        json_obj = json.loads(json_content)
    except json.JSONDecodeError:
        return None

    # Extract the value associated with the given key
    if key in json_obj:
        return json_obj[key]
    else:
        return None

