def convert_xml(data: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    # Iterate over each element in the input list
    for element in data:
        # Check if there are any children in the current element
        if 'children' in element:
            # Recursively call the function to process each child
            element['children'] = convert_xml(element['children'])
        # Remove the 'children' key if it is empty after recursion
