    """
    Generates a list of URL patterns that correspond to the provided actions.
    Each action maps to a corresponding HTTP method: 'list' to GET, 'create' to POST, 'retrieve' to GET with an ID,
    'update' to PUT with an ID, and 'delete' to DELETE with an ID.
    :param actions: List of action names (strings)
    :param base_path: Optional base path (string)
    :return: List of URL patterns
    """
    url_patterns = []
    for action in actions:
        if action == 'list':
            url_patterns.append(f'/{base_path}/')
        elif action == 'create':
            url_patterns.append(f'/{base_path}/')
        elif action == 'retrieve':
            url_patterns.append(f'/{base_path}/<id>/')
        elif action == 'update':
            url_patterns.append(f'/{base_path}/<id>/')
        elif action == 'delete':
            url_patterns.append(f'/{base_path}/<id>/')
        else:
            raise ValueError(f'Invalid action: {action}')
    return url_patterns

